function nvHull(L,W,H,cols){const nL=36,nS=14,pos=[],col=[],idx=[],tmp=new THREE.Color();
const prof=u=>{const a=Math.abs(u);return{w:Math.pow(Math.max(0,1-Math.pow(a,2.3)),.55),sheer:H*(.05+1.15*Math.pow(a,3.2)),keel:H*.45*Math.pow(a,2)}};
for(let i=0;i<=nL;i++){const u=i/nL*2-1,p=prof(u),hw=W/2*p.w;for(let j=0;j<=nS;j++){const th=Math.PI*j/nS,x=-Math.cos(th)*hw,gyv=H*.95+p.sheer,ky=p.keel,y=ky+(gyv-ky)*(1-Math.sin(th)*(1-.0)),t=(y-ky)/Math.max(.001,(gyv-ky));
pos.push(x,y,u*L/2);tmp.setHex(t>.86?cols.trim:t>.6?cols.main:t>.36?cols.band:cols.dark);col.push(tmp.r,tmp.g,tmp.b)}}
for(let i=0;i<nL;i++)for(let j=0;j<nS;j++){const a=i*(nS+1)+j,b=a+1,c=a+nS+1,d=c+1;idx.push(a,c,b,b,c,d)}
const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('color',new THREE.Float32BufferAttribute(col,3));g.setIndex(idx);g.computeVertexNormals();return{g,prof}}
