const post=new THREE.Mesh(new THREE.CylinderGeometry(.035,.045,1.5,6),NV_WOOD);post.position.set(0,by+.7,bz);g.add(post);
const lan=new THREE.Mesh(new THREE.SphereGeometry(.2,10,8),new THREE.MeshBasicMaterial({color:0xffb040}));lan.position.set(0,by+1.25,bz+.12);g.add(lan);
