const sz=L/2-.4,sp=hv.prof(-sz/(L/2));const sp2=new THREE.Mesh(new THREE.CylinderGeometry(.03,.04,1.0,6),NV_WOOD);sp2.position.set(0,H*.95+sp.sheer+.45,-sz);g.add(sp2);
const lan2=new THREE.Mesh(new THREE.SphereGeometry(.14,8,6),new THREE.MeshBasicMaterial({color:0xffc060}));lan2.position.set(0,H*.95+sp.sheer+1,-sz);g.add(lan2);
// canopy (chhatri)
