/* ===== v18: GTA-style smart camera + GLB trees/lamps + automatic water-park door ===== */
const GC={d:5.2,p:.3,ay:null,rs:7,t:0};
function gcam(dt,ins){
const H=window.HM,inH=!!(H&&H.on&&H.inside),ind=inH||ins;
if(GC.ay===null){GC.ay=P.y+1.5;GC.d=CD}
GC.ay+=(P.y+1.5-GC.ay)*(1-Math.exp(-dt*9));const py=GC.ay;
if(inH&&H.cw){GC.t-=dt;if(GC.t<=0){GC.t=.15;let sm=0;for(let k=0;k<8;k++){const a=k*PI/4,sa=Math.sin(a),ca=Math.cos(a);let r=7;for(let q=.4;q<7;q+=.35)if(H.cw(P.x+sa*q,P.y+1.2,P.z+ca*q)){r=q;break}sm+=r}GC.rs+=(sm/8-GC.rs)*.5}}else GC.rs+=(7-GC.rs)*Math.min(1,dt*2);
const zf=clamp(CD/5.2,.6,1.5),want=ind?clamp(GC.rs*.72,2.2,5.2)*zf:CD;
const ceil=H&&H.inU?5.45:2.6,sy=Math.sin(CY),cy=Math.cos(CY),outd=!ind&&P.y<2;
let pt=ind?clamp(CP,.16,.85):clamp(CP,.06,1.35);
if(inH)pt=Math.min(pt,Math.max(.12,Math.asin(clamp((ceil-py)/Math.max(want,1),0,1))));
const trace=(p,dm,uc)=>{const pc=Math.cos(p),sp=Math.sin(p);let best=dm;for(let t=.5;t<=dm;t+=.14){const x=P.x+sy*pc*t,y=py+sp*t,z=P.z+cy*pc*t;let hit=y<gy(x,z)+.35||(uc&&y>ceil);
if(!hit&&H&&H.on&&H.cw&&H.near(x,z)&&H.cw(x,y,z))hit=true;
if(!hit&&outd){for(const c of cols){if(c[2]-c[0]>2.2&&x>c[0]&&x<c[2]&&z>c[1]&&z<c[3]&&y<14){hit=true;break}}}
if(hit){best=t-.14;break}}return Math.max(.9,best-.25)};
let d1=trace(pt,want,inH),low=inH;
if(inH&&d1<1.9){pt=Math.max(pt,.95);d1=trace(pt,want,false);low=false}
if(H)H.camLow=low?1:0;
GC.d+=(d1-GC.d)*(1-Math.exp(-dt*(d1<GC.d?18:2.8)));GC.p+=(pt-GC.p)*(1-Math.exp(-dt*(ind?6:16)));
return{d:GC.d,p:GC.p,y:py}}

